/// <FUN>
void FIUIGDiagtimeStop(int index,long time)
{
  long StopDiagtime;
  long DTCtime;
  StopDiagtime   =  time+10;
  DTCtime        =  Fault_array[index].time;

  if(StopDiagtime>DTCtime)
  { 
    IGoFF();
    testWaitForTimeout(StopDiagtime - DTCtime);  
    FIU_switch(index);    
    testWaitForTimeout(DTCtime);
  }
  else
  {  
    FIU_switch(index); 

    if((DTCtime - StopDiagtime)>0)
    { 
      testWaitForTimeout(DTCtime - StopDiagtime);
    }    
    IGoFF();
    if((StopDiagtime)>0)
    { 
      testWaitForTimeout(StopDiagtime);
    }    
  }
  TestStep_ReadDTC("",Fault_array[index].DTC,1,0,0,1); 
  FIUreset(index); 
}
/// <FUN>
void FIUVoltDiagtimeStop(int index,sysvarFloat *var,float LowVolt,float HigVolt, long time)
{
  long StopDiagtime;
  long DTCtime;
  StopDiagtime   =  time+10;
  DTCtime        =  Fault_array[index].time;

  if(StopDiagtime>DTCtime)
  { 

    VoltSet(LowVolt-0.2);
    SignalWaitCheck(var,LowVolt-1,LowVolt,100); 
    testWaitForTimeout(StopDiagtime - DTCtime);  
    FIU_switch(index);    
    testWaitForTimeout(DTCtime);
  }
  else
  {  
    FIU_switch(index); 

    if((DTCtime - StopDiagtime)>0)
    { 
      testWaitForTimeout(DTCtime - StopDiagtime);
    }    

    VoltSet(LowVolt-0.2);
    SignalWaitCheck(var,LowVolt-1,LowVolt,100); 

    if((StopDiagtime)>0)
    { 
      testWaitForTimeout(StopDiagtime);
    }    
  }
  TestStep_ReadDTC("",Fault_array[index].DTC,1,0,0,1); 
  FIUreset(index); 

  VoltSet(12);
  testWaitForTimeout(3000);

  if(StopDiagtime>DTCtime)
  { 

    VoltSet(HigVolt+0.2);
    SignalWaitCheck(var,HigVolt,HigVolt+1,100); 
    testWaitForTimeout(StopDiagtime - DTCtime);  
    FIU_switch(index);    
    testWaitForTimeout(DTCtime);
  }
  else
  {  
    FIU_switch(index); 

    if((DTCtime - StopDiagtime)>60)
    { 
      testWaitForTimeout(DTCtime - StopDiagtime);
    }    

    VoltSet(HigVolt+0.2);
    SignalWaitCheck(var,HigVolt,HigVolt+1,100); 

    if((StopDiagtime)>0)
    { 
      testWaitForTimeout(StopDiagtime);
    }    
  }
  TestStep_ReadDTC("",Fault_array[index].DTC,1,0,0,1); 
  FIUreset(index);   
}
/// <FUN>
void FIUCreset(int Fault_Type)
{
  int index,listindex,i,j,Time;
  dword DTClist[50];
  index=0;listindex=0;
  for(j=0;j<elcount(Fault_array);j++)
    {
      if(Fault_array[j].Fault_Type == Fault_Type)
      {
        for(i=0;i<listindex;i++)
        { 
          if(Fault_array[j].DTC==DTClist[i])
          {break;}
        }
        if(i==listindex)
        {
          DTClist[listindex]=Fault_array[j].DTC;
          Time=_max(Time,Fault_array[j].time);
          switch(Fault_Type)
           {
             case(Lose):
               testenableMsg(Fault_array[j].Fault);
               break;
             case(Dlc):
              testResetMsgDlc(Fault_array[j].Fault);
               break;  
             case(Crc):
              putValue(Fault_array[j].Fault,0);
               break;  
             case(Counter):
              putValue(Fault_array[j].Fault,0);
               break;  
             case(Invalid):
              testResetSignalValue(lookupSignal(Fault_array[j].Fault));
               break;  
             case(RowInvalid):
              testResetSignalValue(lookupSignal(Fault_array[j].Fault));
               break;
           }          
          listindex++;
        }        
      }    
  }
    if(Time)
    {testWaitForTimeout(Time);}

}
