byte ReadOCC(dword DTC,byte OCC_Num,byte OCCValue,int Period)
{
    int retVal,i;    
    long retSize ;
    dword ResDTC;
    dword DTC_H,DTC_M,DTC_L;
    diagRequest  *  diagReq;
    diagSetTarget ("ABS_ESP");

    // 这样些可以不依赖dbc文件的定义，方便平台共用，也可以使用dbc中定义的诊断名称
    diagResize(diagReq,6);
    DiagSetPrimitiveByte(diagReq,0,0x19);
    DiagSetPrimitiveByte(diagReq,1,0x06);
    DiagSetPrimitiveByte(diagReq,2,DTC>>16); 
    DiagSetPrimitiveByte(diagReq,3,DTC>>8&0xFF); 
    DiagSetPrimitiveByte(diagReq,4,DTC&0xFF); 
    DiagSetPrimitiveByte(diagReq,5,OCC_Num); 

    //send and wait response
    TestReportWriteDiagObject(diagReq);    
    DiagSendRequest(diagReq);
    TestWaitForDiagRequestSent(diagReq, 150);    
    Period-=(int)(testGetLastWaitElapsedTimeNS()/1000000);
    retVal = TestWaitForDiagResponse(diagReq, 1000);    //Get last response
    Period-=(int)(testGetLastWaitElapsedTimeNS()/1000000);
    TestReportWriteDiagResponse(diagReq);   // write response to report
    //write("***************retVal:%d",retVal);
    //writeEx(-3,0,"FDC10 0x%X  %X  %X",DTC,OCCValue,(byte)diagGetRespPrimitiveByte(diagReq,7));
    if(retVal != 1)
    {
      testStepWarning("读取FDC","Response Code is %d",retVal);return 0;
    }
    else{     
         DTC_H = (byte)diagGetRespPrimitiveByte(diagReq,2);
         DTC_M = (byte)diagGetRespPrimitiveByte(diagReq,3);
         DTC_L = (byte)diagGetRespPrimitiveByte(diagReq,4);
         ResDTC = DTC_H<<16 | DTC_M<<8 | DTC_L ;   
         if(OCCValue!=0)
         {
          if(ResDTC==DTC)
          {
             if(OCCValue==(byte)diagGetRespPrimitiveByte(diagReq,7))
             {TestSteppass("读取FDC","FDC%X读取值为%02X",OCC_Num,(byte)diagGetRespPrimitiveByte(diagReq,7));}
             else 
             {testStepFail("读取FDC","FDC%X读取值为%02X,应为%X",OCC_Num,(byte)diagGetRespPrimitiveByte(diagReq,7),OCCValue);}  
          }
          else
          { //write("***************retVal:%X  %X",ResDTC,DTC);
            testStepFail("读取FDC","FDC%X读取值为%02X",OCC_Num,OCCValue);

          }
        }
        else
        {
          testStepWarning("读取FDC","FDC%X读取值为%02X",OCC_Num,OCCValue);
          writeex(-3,1,"读取FDC","FDC%X读取值为%02X",OCC_Num,OCCValue);
        }
     }
    if(Period>0)
    testwaitfortimeout(Period);
  return (byte)diagGetRespPrimitiveByte(diagReq,5);
}
